struct Keyframe { float frame, value, tangent; };
template<std::size_t N> inline float sample(const Keyframe (&keys)[N], float frame) {
    if (frame < keys[0].frame) return keys[0].value;
    std::size_t next=0;
    while (next<N && keys[next].frame<=frame) ++next;
    if (next==N) return keys[N-1].value;
    const auto &a=keys[next-1], &b=keys[next];
    const float span=b.frame-a.frame;
    const float t=std::clamp((frame-a.frame)/span,0.0f,1.0f), t2=t*t, t3=t2*t;
    return (2*t3-3*t2+1)*a.value+(t3-2*t2+t)*span*a.tangent+
           (-2*t3+3*t2)*b.value+(t3-t2)*span*b.tangent;
}
// All public scalar functions accept ORIGINAL animation frames, not spring progress.
// Nonlooping tracks clamp at their end. Looping tracks wrap by their authored period.
inline float loop_frame(float frame, float period) {
    const float wrapped=std::fmod(frame,period);
    return wrapped<0.0f ? wrapped+period : wrapped;
}
